const { keysetPage } = require('./pager');
const { encodeCursor, decodeCursor } = require('./cursor');
const { clampLimit } = require('./limits');

function newestFirst(a, b) {
  return b.createdAt - a.createdAt || (a.id < b.id ? 1 : a.id > b.id ? -1 : 0);
}

function feedPage(events, { after, limit } = {}) {
  const sorted = [...events].sort(newestFirst);
  const page = keysetPage(sorted, after ? decodeCursor(after) : null, clampLimit(limit), (e) => e.createdAt);
  const last = page.items[page.items.length - 1];
  return { items: page.items, next: page.more ? encodeCursor(last.createdAt) : null };
}

module.exports = { feedPage };
