const { keysetPage } = require('./pager');

function commentsPage(comments, { after, limit = 50 } = {}) {
  const sorted = [...comments].sort((a, b) => b.postedAt - a.postedAt || (a.id < b.id ? 1 : -1));
  const page = keysetPage(sorted, after ? [after.postedAt, after.id] : null, limit, (c) => [c.postedAt, c.id]);
  const last = page.items[page.items.length - 1];
  return { items: page.items, next: page.more ? { postedAt: last.postedAt, id: last.id } : null };
}

module.exports = { commentsPage };
